+
+import "testing"
+
+func TestParseFailVerdict(t *testing.T) {
+	v, err := Parse(`{"verdict":"fail","reason":"no test added"}`)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if v.Pass || v.Reason != "no test added" {
+		t.Errorf("Parse = %+v, want a fail verdict with its reason", v)
+	}
+}

